contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address _log, bool initializeFirst) public payable {
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint256 ethBefore = address(c).balance;
        bool reverted;
        c.SetLogFile(_log); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted == (initializeFirst || true) && address(c).balance == ethBefore);
    }

    receive() external payable {}
}

